const version = readFileSync(join(ROOT, 'src/sdk/version.ts'), 'utf8').match(/'([^']+)'/)[1];
const banner = `/* edge-personalization SDK v${version} — one package: core (identity, transport), emit (four capture paths), listen (decisions). */`;
const common = { bundle: true, platform: 'browser', target: 'es2022', minify: false, sourcemap: false,
 legalComments: 'none', logLevel: 'info', metafile: true, banner: { js: banner }, write: false };
const outputs = [];
for (const [entry, output, format] of [['src/sdk/index.ts', 'public/sdk/edge-personalization.esm.js', 'esm'], ['src/sdk/browser.ts', 'public/sdk/edge-personalization.js', 'iife']]) {
 const built = await esbuild.build({ ...common, entryPoints: [join(ROOT, entry)], outfile: join(ROOT, output), format });
 const generated = built.outputFiles[0].contents, disk = readFileSync(output);
