import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
import * as esbuild from 'esbuild';
const root = 'docs/remediation/evidence/W04.01/';
const read = path => JSON.parse(readFileSync(path, 'utf8'));
const hash = data => createHash('sha256').update(data).digest('hex');
const artifact = read(root+'artifact-v1.json'), graph = read(root+'source-inputs-v1.json'), worker = read(root+'worker-checks.json');
const digest = hash(JSON.stringify({contract_digest:artifact.contract_digest,configuration:artifact.configuration,files:artifact.files.map(({path,sha256,role})=>({path,sha256,role})).sort((a,b)=>a.path.localeCompare(b.path))}));
assert.equal(digest,'a8d7eff3a36ce88b80323c3f53b9efe2f21f4425466ca76be99d6a6571b494cc');
assert.equal(artifact.digest,digest); assert.equal(artifact.files.length,63);
const pins = new Map(artifact.files.map(f=>[f.path,f.sha256])); assert.equal(pins.size,63);
for(const f of artifact.files) assert.equal(hash(readFileSync(f.path)),f.sha256,f.path);
const entryPoints=['src/identity/identity.test.ts','src/routes/identity.test.ts','src/sdk/identify.test.ts','src/sdk/index.ts','src/sdk/browser.ts'];
const options={entryPoints,bundle:true,packages:'external',platform:'node',format:'esm',target:'es2022',write:false,metafile:true,logLevel:'silent',outdir:'/tmp/w0401-graph-unused',outbase:'.'};
assert.deepEqual(options,graph.graph.options);
const result=await esbuild.build(options);
const actualGraph=Object.keys(result.metafile.inputs).sort().map(path=>({path,sha256:hash(readFileSync(path))}));
assert.deepEqual(actualGraph,graph.graph.files); assert.equal(actualGraph.length,41);
for(const f of actualGraph) assert.equal(pins.get(f.path),f.sha256,f.path);
assert.equal(worker.sourceFiles.length,11); for(const f of worker.sourceFiles) assert.equal(pins.get(f.path),f.sha256,f.path);
const originals=read(root+'before-sources-v1.json').files;
assert.equal(originals.length,11); for(const f of originals) assert.equal(hash(f.text),f.sha256,f.path);
const oldRoute=originals.find(f=>f.path==='src/routes/identity.test.ts').text, currentRoute=readFileSync('src/routes/identity.test.ts','utf8');
const marker="describe('erase: the right to be forgotten";
assert.ok(oldRoute.includes(marker)); assert.ok(currentRoute.includes(marker));
assert.equal(currentRoute.slice(currentRoute.indexOf(marker)).replaceAll('await signedCall(','await call('),oldRoute.slice(oldRoute.indexOf(marker)));
const oldJwt=oldRoute.split('\n').find(s=>s.startsWith('const token =')); assert.ok(oldJwt); assert.ok(currentRoute.split('\n').includes(oldJwt));
const prior=read(root+'tracker-before-v1.json').tasks.find(t=>t.id==='W07.04').artifact;
const expectedChanges=['src/identity/assertion.ts','src/routes/identity.ts','src/types/env.ts'];
const actualChanges=prior.files.filter(f=>hash(readFileSync(f.path))!==f.sha256).map(f=>f.path).sort();
assert.deepEqual(actualChanges,[...expectedChanges].sort());
const entry=read(root+'entry-checks-v1.json');
console.log(JSON.stringify({artifactDigest:digest,manifestFileSha256:hash(readFileSync(root+'artifact-v1.json')),physicalPins:63,mismatches:0,actualGraph,workerOutputs:worker.sourceFiles,originalHashesValidated:11,originalErasureAndJwtAssertionsPreserved:true,protectedPriorPins:prior.files.length-actualChanges.length,declaredPriorChanges:actualChanges,inspectedEvidence:[root+'worker.md',root+'worker-checks.json',root+'baseline.json',root+'baseline-probe.mjs',root+'before-sources-v1.json',root+'source-inputs-v1.json'].map(path=>({path,sha256:hash(readFileSync(path))})),entry:{trustedSequence:entry.trustedSequence,trustedTrackerSha256:entry.trustedTrackerSha256,sourceSha256:entry.sourceSha256,checkExit:entry.check.result.exit_code},limits:'Relevant packages-external local graph and physical identity only; not installed packages, full TypeScript program, deployed/runtime/customer proof or prior-contract reclosure.'},null,2));
